// Generated by scripts/sync-core.mts from packages/core/src. Do not edit; run `pnpm sync:core`.
// Page-aware chunking for retrieval (10 MVP-01, 04 §6). gte-small truncates at 512 word-pieces and
// the spec caps chunks at 350 with 50 overlap (02 §1). There is no tokenizer here, so words stand in:
// English prose runs about 1.3 word-pieces per word, so 260 words ≈ 340 word-pieces. A character
// cap keeps symbol-heavy text (formulas, tables) under the limit too.

export type PageText = { page: number | null; text: string };
export type TextChunk = { page: number | null; content: string };

export const CHUNK_MAX_WORDS = 260;
export const CHUNK_OVERLAP_WORDS = 38;
export const CHUNK_MAX_CHARS = 1600;
/** A page shorter than this joins the next page's chunk instead of standing alone. */
export const CHUNK_MIN_WORDS = 40;

// Control characters other than tab and newline (pdf.js leaves some in extracted text).
const CONTROL = /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g;

export function cleanText(text: string): string {
  return text.replace(CONTROL, " ").replace(/\s+/g, " ").trim();
}

/**
 * Splits pages into chunks of at most CHUNK_MAX_WORDS words and CHUNK_MAX_CHARS characters.
 * Chunks never span two pages unless a page is too short to stand alone; each chunk keeps the page
 * it starts on (for "From your notes, p. 12" citations). Long pages split with an overlap.
 */
export function chunkPages(pages: PageText[]): TextChunk[] {
  const out: TextChunk[] = [];
  let buf: string[] = [];
  let bufPage: number | null = null;
  let bufChars = 0;

  const emit = () => {
    if (buf.length > 0) out.push({ page: bufPage, content: buf.join(" ") });
    buf = [];
    bufChars = 0;
  };

  for (const { page, text } of pages) {
    const words = cleanText(text).split(" ").filter(Boolean);
    if (words.length === 0) continue;
    // Page boundary: a buffer long enough to stand alone becomes its own chunk.
    if (buf.length >= CHUNK_MIN_WORDS) emit();
    if (buf.length === 0) bufPage = page;

    for (const raw of words) {
      // A single "word" longer than the cap (a URL, a run of symbols) is cut to fit.
      const word = raw.length > CHUNK_MAX_CHARS ? raw.slice(0, CHUNK_MAX_CHARS) : raw;
      const extra = word.length + (buf.length > 0 ? 1 : 0);
      if (buf.length >= CHUNK_MAX_WORDS || bufChars + extra > CHUNK_MAX_CHARS) {
        const tail = buf.slice(-CHUNK_OVERLAP_WORDS);
        emit();
        // Overlap carries into the next chunk only within the same page.
        bufPage = page;
        buf = tail;
        bufChars = tail.join(" ").length;
        // Drop overlap words from the front if the carried tail plus this word would still be too long.
        while (buf.length > 0 && bufChars + word.length + 1 > CHUNK_MAX_CHARS) {
          const dropped = buf.shift()!;
          bufChars = Math.max(0, bufChars - dropped.length - 1);
        }
      }
      bufChars += word.length + (buf.length > 0 ? 1 : 0);
      buf.push(word);
    }
  }
  emit();
  return out;
}
